cd "E:/Projects/Code/AI/Ji/.gold-band/worktrees/task-025/run-001/dyn-e6e6c780246db725" && node -e "
const fs=require('fs'),path=require('path');
for (const m of ['ji-remote-bootstrap','ji-host-web','ji-host-core']) {
  const dirs=fs.globSync('ji-java/*/*/'+m+'/build/test-results/test/*.xml');
  let t=0,f=0,s=0; const names=[];
  for (const p of dirs){const x=fs.readFileSync(p,'utf8');
    const m2=x.match(/tests=\"(\d+)\"[^>]*skipped=\"(\d+)\"[^>]*failures=\"(\d+)\"[^>]*errors=\"(\d+)\"/);
    if(m2){t+=+m2[1];s+=+m2[2];f+=+m2[3]+ +m2[4];names.push(path.basename(p,'.xml'));}}
  console.log(m+': files='+dirs.length+' tests='+t+' failures='+f+' skipped='+s);
  console.log('   '+names.join(', '));
}
"
